INSERT INTO curriculum_topics
  (id, board, exam_year, class_level, subject, unit, topic, learning_objective, source_url, source_retrieved_at, review_status, version)
VALUES
  ('topic-viii-squares-cubes-puzzles-sets', 'CISCE', NULL, 'VIII', 'Mathematics', 'Number System', 'Squares, square roots, cubes, cube roots, number puzzles and sets', 'Evaluate squares, square roots, cubes, and cube roots; apply divisibility and algebraic place-value logic to number puzzles; and execute operations on sets including union, intersection, and complement.', 'https://cisce.org/wp-content/uploads/2025/03/UpperPrimary.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-viii-percentages-profit-discount-tax', 'CISCE', NULL, 'VIII', 'Mathematics', 'Ratio and Proportion', 'Percentages, profit, loss, overheads, discount and tax', 'Calculate percentage adjustments, include overhead charges to find effective cost price, calculate profit or loss percentages, evaluate successive trade discounts, and compute retail sales tax.', 'https://cisce.org/wp-content/uploads/2025/03/UpperPrimary.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-viii-simple-compound-interest', 'CISCE', NULL, 'VIII', 'Mathematics', 'Ratio and Proportion', 'Simple and compound interest', 'Distinguish simple from compound interest, calculate compound interest and accumulated amounts using formulas and unit-period steps, and solve half-yearly compounding and depreciation problems.', 'https://cisce.org/wp-content/uploads/2025/03/UpperPrimary.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-viii-variation-time-work', 'CISCE', NULL, 'VIII', 'Mathematics', 'Ratio and Proportion', 'Direct and inverse variation; time and work', 'Recognise and set up equations for direct and inverse variation, solve proportional distribution problems, and calculate work rates and durations for collective and staged tasks.', 'https://cisce.org/wp-content/uploads/2025/03/UpperPrimary.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-viii-algebraic-expressions-identities-factorisation', 'CISCE', NULL, 'VIII', 'Mathematics', 'Algebra', 'Algebraic expressions, identities and factorisation', 'Multiply and divide algebraic expressions, expand products using standard identities, and factorise expressions through common factors, grouping, difference of squares, and middle-term splitting.', 'https://cisce.org/wp-content/uploads/2025/03/UpperPrimary.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-viii-linear-equations-inequalities', 'CISCE', NULL, 'VIII', 'Mathematics', 'Algebra', 'Linear equations and inequalities in one variable', 'Solve linear equations in one variable with rational coefficients, formulate equations from word problems, and solve linear inequalities while displaying solutions on a number line.', 'https://cisce.org/wp-content/uploads/2025/03/UpperPrimary.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-viii-quadrilaterals-euler-solids', 'CISCE', NULL, 'VIII', 'Mathematics', 'Geometry', 'Quadrilaterals, parallelograms and Euler''s relation for solids', 'Apply angle sum and structural properties of quadrilaterals, differentiate types of parallelograms, interpret 3D polyhedral models, and verify Euler''s relation V − E + F = 2.', 'https://cisce.org/wp-content/uploads/2025/03/UpperPrimary.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-viii-construction-symmetry-circles-graphs', 'CISCE', NULL, 'VIII', 'Mathematics', 'Geometry', 'Quadrilateral construction, reflection symmetry, circles and Cartesian graphs', 'Determine criteria for constructing unique quadrilaterals, identify reflection axes, describe circle regions and boundary components, and plot points and interpret linear equations on Cartesian graphs.', 'https://cisce.org/wp-content/uploads/2025/03/UpperPrimary.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-viii-mensuration-polygons-solids', 'CISCE', NULL, 'VIII', 'Mathematics', 'Mensuration', 'Mensuration: trapezia, polygons, semicircles, cubes, cuboids and cylinders', 'Calculate areas of trapezia and semicircular regions; compute surface areas and volumes of cubes, cuboids, and right circular cylinders; and convert solid volumes into liquid capacities.', 'https://cisce.org/wp-content/uploads/2025/03/UpperPrimary.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-viii-grouped-data-charts-probability', 'CISCE', NULL, 'VIII', 'Mathematics', 'Data Handling', 'Grouped data, bar graphs, pie charts and experimental probability', 'Organise data into grouped frequency distributions with class intervals, interpret bar charts and construct pie charts using sector angles, and evaluate experimental probability as empirical relative frequency.', 'https://cisce.org/wp-content/uploads/2025/03/UpperPrimary.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-x-gst', 'CISCE', 2027, 'X', 'Mathematics', 'Commercial Mathematics', 'Goods and Services Tax', 'Compute tax components, input tax credit, discounts, profit, and consumer prices in intra-state and inter-state GST transactions.', 'https://cisce.org/wp-content/uploads/2025/03/9.-Mathematics.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-x-recurring-deposits', 'CISCE', 2027, 'X', 'Mathematics', 'Commercial Mathematics', 'Recurring deposit accounts', 'Calculate simple interest, maturity value, monthly deposit, and time period for recurring deposit accounts using the qualifying sum formula.', 'https://cisce.org/wp-content/uploads/2025/03/9.-Mathematics.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-x-shares-dividends', 'CISCE', 2027, 'X', 'Mathematics', 'Commercial Mathematics', 'Shares and dividends', 'Calculate investment, nominal value, market value, dividend income, and rate of return on shares.', 'https://cisce.org/wp-content/uploads/2025/03/9.-Mathematics.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-x-linear-inequations', 'CISCE', 2027, 'X', 'Mathematics', 'Algebra', 'Linear inequations', 'Solve linear inequations algebraically and represent solution sets on the real number line over N, W, Z, and R.', 'https://cisce.org/wp-content/uploads/2025/03/9.-Mathematics.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-x-ratio-proportion', 'CISCE', 2027, 'X', 'Mathematics', 'Algebra', 'Ratio and proportion', 'Apply proportion properties, continued proportion, mean proportional, and componendo and dividendo to simplify and solve algebraic ratios.', 'https://cisce.org/wp-content/uploads/2025/03/9.-Mathematics.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-x-factor-remainder', 'CISCE', 2027, 'X', 'Mathematics', 'Algebra', 'Factor and remainder theorems', 'Apply the remainder theorem and factor theorem to find remainders, determine unknown coefficients, and completely factorise cubic polynomials.', 'https://cisce.org/wp-content/uploads/2025/03/9.-Mathematics.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-x-matrices', 'CISCE', 2027, 'X', 'Mathematics', 'Algebra', 'Matrices', 'Perform matrix operations including addition, subtraction, scalar multiplication, and 2x2 matrix multiplication, and determine order compatibility.', 'https://cisce.org/wp-content/uploads/2025/03/9.-Mathematics.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-x-progressions', 'CISCE', 2027, 'X', 'Mathematics', 'Algebra', 'Arithmetic and geometric progressions', 'Determine the general nth term and the sum of n terms of arithmetic progressions (AP) and finite geometric progressions (GP).', 'https://cisce.org/wp-content/uploads/2025/03/9.-Mathematics.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-x-coordinate-geometry', 'CISCE', 2027, 'X', 'Mathematics', 'Algebra', 'Coordinate geometry', 'Determine reflections in coordinate axes and origin, calculate section, midpoint, and centroid coordinates, find slopes, and formulate straight-line equations.', 'https://cisce.org/wp-content/uploads/2025/03/9.-Mathematics.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-x-similarity', 'CISCE', 2027, 'X', 'Mathematics', 'Geometry', 'Similarity of triangles', 'Apply similarity criteria (AAA, SAS, SSS), the basic proportionality theorem, and the ratio of areas theorem to solve geometric configurations.', 'https://cisce.org/wp-content/uploads/2025/03/9.-Mathematics.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-x-loci', 'CISCE', 2027, 'X', 'Mathematics', 'Geometry', 'Loci', 'Identify and construct loci of points equidistant from two fixed points, equidistant from two intersecting lines, and at a fixed distance from a point or line.', 'https://cisce.org/wp-content/uploads/2025/03/9.-Mathematics.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-x-circles', 'CISCE', 2027, 'X', 'Mathematics', 'Geometry', 'Circle theorems', 'Apply angle, cyclic quadrilateral, tangent, and secant theorems to determine unknown angles and segment lengths in circles.', 'https://cisce.org/wp-content/uploads/2025/03/9.-Mathematics.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-x-constructions', 'CISCE', 2027, 'X', 'Mathematics', 'Geometry', 'Geometrical constructions', 'Determine geometric measurements and properties for compass-and-straightedge constructions of tangents, incircles, and circumcircles of triangles and regular polygons.', 'https://cisce.org/wp-content/uploads/2025/03/9.-Mathematics.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-x-mensuration', 'CISCE', 2027, 'X', 'Mathematics', 'Mensuration', 'Mensuration of solid figures', 'Calculate surface areas and volumes of right circular cylinders, cones, spheres, hemispheres, and combined or recast solids.', 'https://cisce.org/wp-content/uploads/2025/03/9.-Mathematics.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-x-trigonometry', 'CISCE', 2027, 'X', 'Mathematics', 'Trigonometry', 'Trigonometric identities and heights and distances', 'Verify trigonometric identities and solve heights and distances problems involving angles of elevation and depression with at most two right triangles.', 'https://cisce.org/wp-content/uploads/2025/03/9.-Mathematics.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-x-statistics', 'CISCE', 2027, 'X', 'Mathematics', 'Statistics', 'Statistics', 'Calculate mean by direct, assumed mean, and step-deviation methods, determine median, quartiles, and mode using grouped data, histograms, and cumulative frequency curves (ogives).', 'https://cisce.org/wp-content/uploads/2025/03/9.-Mathematics.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-x-probability', 'CISCE', 2027, 'X', 'Mathematics', 'Probability', 'Probability', 'Determine sample spaces and calculate theoretical probabilities of simple, single-stage events including coins, dice, playing cards, and urn models.', 'https://cisce.org/wp-content/uploads/2025/03/9.-Mathematics.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-xii-goodwill-valuation', 'CISCE', 2027, 'XII', 'Accountancy', 'Partnership Accounts', 'Goodwill: valuation and treatment', 'Calculate goodwill using average profit, weighted average, super profit, and capitalisation methods, applying AS-26 principles on reconstitution.', 'https://cisce.org/wp-content/uploads/2025/04/15.-ISC-Accountancy.docx.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-xii-admission-partner', 'CISCE', 2027, 'XII', 'Accountancy', 'Partnership Accounts', 'Admission of a partner', 'Calculate sacrificing and new profit-sharing ratios, account for goodwill and revaluation under AS-26, and adjust partner capital accounts upon admission.', 'https://cisce.org/wp-content/uploads/2025/04/15.-ISC-Accountancy.docx.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-xii-retirement-death', 'CISCE', 2027, 'XII', 'Accountancy', 'Partnership Accounts', 'Retirement and death of a partner', 'Compute gaining ratios, adjust goodwill under AS-26, compute interim profit to date of death, and settle retiring loan or executor accounts.', 'https://cisce.org/wp-content/uploads/2025/04/15.-ISC-Accountancy.docx.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-xii-dissolution-firm', 'CISCE', 2027, 'XII', 'Accountancy', 'Partnership Accounts', 'Dissolution of a partnership firm', 'Apply Section 48 statutory settlement rules, prepare Realisation Account, handle partner loans, and close accounts on dissolution.', 'https://cisce.org/wp-content/uploads/2025/04/15.-ISC-Accountancy.docx.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-xii-issue-of-shares', 'CISCE', 2027, 'XII', 'Accountancy', 'Joint Stock Company Accounts', 'Issue of shares', 'Account for share issues at par and premium, execute pro-rata allotments, handle calls in arrears, and compute forfeiture and reissue transfers to capital reserve.', 'https://cisce.org/wp-content/uploads/2025/04/15.-ISC-Accountancy.docx.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-xii-issue-of-debentures', 'CISCE', 2027, 'XII', 'Accountancy', 'Joint Stock Company Accounts', 'Issue of debentures', 'Record debenture issues at par, premium, or discount, account for collateral security, write off issue losses, and calculate debenture interest with TDS.', 'https://cisce.org/wp-content/uploads/2025/04/15.-ISC-Accountancy.docx.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-xii-redemption-of-debentures', 'CISCE', 2027, 'XII', 'Accountancy', 'Joint Stock Company Accounts', 'Redemption of debentures', 'Apply statutory DRR (10%) and DRI (15%) requirements for specified company categories, and record entries for lump sum debenture redemption.', 'https://cisce.org/wp-content/uploads/2025/04/15.-ISC-Accountancy.docx.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-xii-final-accounts-companies', 'CISCE', 2027, 'XII', 'Accountancy', 'Joint Stock Company Accounts', 'Final accounts of companies', 'Classify corporate assets and liabilities under Schedule III Part I major heads and sub-heads, and prepare detailed Notes to Accounts.', 'https://cisce.org/wp-content/uploads/2025/04/15.-ISC-Accountancy.docx.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-xii-financial-statement-analysis', 'CISCE', 2027, 'XII', 'Accountancy', 'Management Accounting', 'Financial statement analysis', 'Prepare and interpret comparative statements (horizontal analysis) and common-size statements (vertical analysis) for Balance Sheets and Profit and Loss Statements.', 'https://cisce.org/wp-content/uploads/2025/04/15.-ISC-Accountancy.docx.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-xii-cash-flow-statement', 'CISCE', 2027, 'XII', 'Accountancy', 'Management Accounting', 'Cash flow statement', 'Prepare a Cash Flow Statement under AS-3 using the indirect method, properly classifying operating, investing, and financing flows for a manufacturing company.', 'https://cisce.org/wp-content/uploads/2025/04/15.-ISC-Accountancy.docx.pdf', '2026-10-20', 'reviewed', 1),
  ('topic-xii-ratio-analysis', 'CISCE', 2027, 'XII', 'Accountancy', 'Management Accounting', 'Ratio analysis', 'Compute and interpret liquidity, solvency, activity, and profitability ratios respecting ISC syllabus rules on gross versus net trade receivables.', 'https://cisce.org/wp-content/uploads/2025/04/15.-ISC-Accountancy.docx.pdf', '2026-10-20', 'reviewed', 1);
