-- Complete reviewed course roadmaps for the three initial Home Study tracks.
-- Student-visible lessons and diagnostics are original and source-linked.

PRAGMA foreign_keys = ON;

ALTER TABLE assignment_templates ADD COLUMN sequence INTEGER NOT NULL DEFAULT 1 CHECK (sequence >= 1);
DROP INDEX assignment_templates_active_class_subject;
UPDATE assignment_templates SET sequence = 5 WHERE id = 'template-x-quadratics';
CREATE UNIQUE INDEX assignment_templates_active_class_subject_sequence
  ON assignment_templates (class_level, subject, sequence)
  WHERE active = 1 AND review_status = 'reviewed';









